import React from 'react';

import Trophy from '@pohodnik/icons/svg/RealWorld/Trophy';
import { useNavigate } from 'react-router-dom';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import { getWorkoutsTargets } from '../@services/workoutsTargets.service';
import { IWorkoutTarget } from '../@types/workoutsTargets.types';
import WorkoutTargetItem from '../components/WorkoutTargets/WorkoutTargetItem';

const WorkoutTargetsListPage: React.FC = () => {
  const [data, setData] = React.useState<IWorkoutTarget[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [isActual, setIsActual] = React.useState(true);
  const [my, setMy] = React.useState(false);
  const [err, setErr] = React.useState<Error>();

  const navigate = useNavigate();
  React.useEffect(() => {
    const fetchData = async () => {
      try {
        const d = await getWorkoutsTargets({ my, actual: isActual });
        setData(d);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [isActual, my]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <section>
      <>
        <Breadcrumb
          data={[
            { href: `/workouts`, text: 'Тренировки' },
            { href: `/workouts/targets`, text: 'Цели', active: true },
          ]}
        />
        <PohContainer>
          <PageHeader title="Цели тренировок">
            <div className="d-flex align-items-center">
              <PohButton
                size={ButtonSize.Small}
                variant={ButtonVariant.Success}
                onClick={() => navigate(`/workouts/targets/new`)}
              >
                Добавить цель
              </PohButton>
            </div>
          </PageHeader>
          <div className="d-flex" style={{ gap: 24 }}>
            <PohCheckbox onChange={setIsActual} checked={isActual} label="Скрыть завершенные" />
            &nbsp;
            <PohCheckbox onChange={setMy} checked={my} label="Только мои" />
          </div>
          <PohRow>
            <PohCol sm={12}>
              {!data.length && (
                <Empty icon={<Trophy />}>
                  <p className="text-center">
                    <small>
                      Можете добавить свои цели или присоединиться к общедоступным!
                      <br />
                      Вам останется только следить за прогрессом выполнения загружая тренировки
                    </small>
                  </p>
                </Empty>
              )}
              <PohList
                data={data.map((target) => {
                  return {
                    key: target.id,
                    content: <WorkoutTargetItem data={target} />,
                    action: true,
                    onClick: () => navigate(`/workouts/targets/${target.id}`),
                  };
                })}
              />
            </PohCol>
          </PohRow>
        </PohContainer>
      </>
    </section>
  );
};

export default WorkoutTargetsListPage;
